CREATE TABLE IF NOT EXISTS `hipsskymaps` (
    `id` TEXT NOT NULL,
    `shortname` TEXT NOT NULL,
    `longname` TEXT NOT NULL,
    `path` TEXT NOT NULL,
    `band` TEXT,
    `coverage` REAL,
    `comment` TEXT,
    PRIMARY KEY(`id`)
);

INSERT OR REPLACE INTO hipsskymaps(id, shortname, longname, path, band, coverage, comment)
VALUES
    ('DSS2_COLOR','DSS2 Color','Digitized Sky Survey Color','CDS/P/DSS2/color','400-600 nm',100,'Color composition generated by CDS. This HiPS survey is based on 2 others HiPS surveys, respectively DSS2-red and DSS2-blue HiPS, both of them directly generated from original scanned plates downloaded from STScI site. The red component has been built from POSS-II F, AAO-SES,SR and SERC-ER plates. The blue component has been build from POSS-II J and SERC-J,EJ. The green component is based on the mean of other components. Three missing plates from red survey (253, 260, 359) has been replaced by pixels from the DSSColor STScI jpeg survey. The 11 missing blue plates (mainly in galactic plane) have not been replaced (only red component).'),
    ('DSS2_RED','DSS2 Red','Digitized Sky Survey Red','CDS/P/DSS2/red','640-658 nm',100,'The Catalogs and Surveys Group of the Space Telescope Science Institute has digitized the photographic Sky survey plates from the Palomar and UK Schmidt telescopes to produce the "Digitized Sky Survey" (DSS). Each plate covers 6.5 x 6.5 degrees of the sky and have been digitized using a modified PDS microdensitometer. DSS2F north is the digitalization of the POSS2/UKSTU Red survey (0.658um). DSS2R south is the digitalization of the AAO Red survey (0.64um). The all-sky HEALPix resampling has been done by the CDS'),
    ('DSS2_BLUE','DSS2 Blue','Digitized Sky Survey Blue','CDS/P/DSS2/blue','468-491 nm',99.67,'The Catalogs and Surveys Group of the Space Telescope Science Institute has digitized the photographic Sky survey plates from the Palomar and UK Schmidt telescopes to produce the "Digitized Sky Survey"(DSS). Each plate covers 6.5 x 6.5 degrees of the sky and have been digitized using a modified PDS microdensitometer. The DSS blue HiPS is a combination of DSS2-XJ and DSS2-S. DSS2-XJ north is the digitalization of the POSS-II J (1987-1998 - 0.491um) from Caltech,DSS2-S south is the digitalization of the SERC-J (1975-1987 - 0.468um) and SERC-EJ (1979-1988 - 0.468um) from ROE.The all-sky HEALPix resampling has been done by the CDS with the help of CADC.'),
    ('DSS2_NIR','DSS2 NIR','Digitized Sky Survey Near Infrared','CDS/P/DSS2/NIR','700-950 nm',99.55,'The Catalogs and Surveys Group of the Space Telescope Science Institute has digitized the photographic Sky survey plates from the Palomar and UK Schmidt telescopes to produce the "Digitized Sky Survey"(DSS). Each plate covers 6.5 x 6.5 degrees of the sky and have been digitized using a modified PDS microdensitometer. The DSS NIT HiPS is a combination of DSS2-XI and DSS2-IS. DSS2-XI north is the digitalization of the POSS-II N (1987-2002 - filter: IV-N +RG9) from Caltech, DSS2-IS south is the digitalization of the SERC-IS (1990-2002 - filter: IV-N +RG175). The all-sky HEALPix resampling has been done by the CDS with the help of CADC.'),
    ('CTA-FRAM','CTA-FRAM Color','CTA-FRAM Sky Survey Color','fzu.cz/P/CTA-FRAM/survey/color','380-800 nm',100,'All-sky survey performed by CTA-FRAM wide-field cameras installed at Observatorio del Roque de los Muchachos (La Palma, Spain) and Paranal Observatory (Chile). The cameras are primarily intended for atmosoheric characterization of the future Cherenkov Telescope Array (CTA) sites, and are based on Zeiss 135/2.0 lenses and Moravian Instruments G4-16000 CCDs, providing 15x15 deg fields of view with 14.1''/pix pixel scale. The cameras are equipped with Johnson-Cousins B, V, R, and I filters. Copyright: Institute of Physics, Czech Academy of Sciences.'),
    ('2MASS_COL','2MASS Color','The Two Micron All Sky Survey','CDS/P/2MASS/color','1.15-2.3 um',100,'MASS has uniformly scanned the entire sky in three near-infrared bands to detect and characterize point sources brighter than about 1 mJy in each band, with signal-to-noise ratio (SNR) greater than 10, using a pixel size of 2.0". This has achieved an 80,000-fold improvement in sensitivity relative to earlier surveys. 2MASS used two highly-automated 1.3-m telescopes, one at Mt. Hopkins, AZ, and one at CTIO, Chile. Each telescope was equipped with a three-channel camera, each channel consisting of a 256x256 array of HgCdTe detectors, capable of observing the sky simultaneously at J (1.25 microns), H (1.65 microns), and Ks (2.17 microns). The University of Massachusetts (UMass) was responsible for the overall management of the project, and for developing the infrared cameras and on-site computing systems at both facilities. The Infrared Processing and Analysis Center (IPAC) is responsible for all data processing through the Production Pipeline, and construction and distribution of the data products. Funding is provided primarily by NASA and the NSF'),
    ('MELLINGER','Mellinger Color','Axel Mellingers Milky Way Panorama 2.0','CDS/P/Mellinger/color','400-800 nm',100,'Using a portable low-cost CCD camera system, 70 fields (each covering 40deg x 27deg) were imaged over a time span of 22 months from dark-sky locations in South Africa, Texas, and Michigan. The fields were photometrically calibrated against standard catalog stars. Using sky background data from the Pioneer 10 and 11 space probes, gradients resulting from artificial light pollution, airglow, and zodiacal light were eliminated, while the large-scale galactic and extragalactic background resulting from unresolved sources was preserved. The 648 megapixel image is a valuable educational tool, being able to fully utilize the resolution and dynamic range of modern full-dome planetarium projection systems. Copyright 2000-2017 Axel Mellinger. All rights reserved.'),
    ('TC8','NSNS True-color','Northern Sky Narrowband Survey DR0.1 Color','simg.de/P/NSNS/DR0_1/tc8','440-700 nm',65.1,'Almost true-color composite without star subtraction as compressed 8-bit color HIPS for easy visualization. See http://www.simg.de/nebulae3/dr0_1 for other data sets. Northern Sky Narrowband Survey by Stefan Ziegenbalg.'),
    ('HBR8','NSNS H-alpha and continuum','Northern Sky Narrowband Survey DR0.2 H-alpha and continuum','simg.de/P/NSNS/DR0_2/hbr8','440-700 nm',64.84,'H-alpha (without continuum, mapped to red), blue continuum (mapped to green) and red continuum (mapped to blue) as compressed 8-bit color HIPS for easy visualization. Stars are partially subtracted to make the faint refelction nebulae visible. See http://www.simg.de/nebulae3/dr0_2 for other data sets. Northern Sky Narrowband Survey by Stefan Ziegenbalg.'),
    ('RGB8','NSNS RGB continuum','Northern Sky Narrowband Survey DR0.2 RGB continuum','simg.de/P/NSNS/DR0_2/rgb8','440-700 nm',65.1,'Red, green and blue continuum with partially subtracted stars as compressed 8-bit color HIPS for easy visualization. See http://www.simg.de/nebulae3/dr0_2 for other data sets. Northern Sky Narrowband Survey by Stefan Ziegenbalg.'),
    ('HA8','NSNS H-alpha','Northern Sky Narrowband Survey DR0.2 H-alpha','simg.de/P/NSNS/DR0_2/halpha8','656.3 nm',64.64,'H-alpha (without continuum) as compressed 8-bit HIPS for easy visualization. See http://www.simg.de/nebulae3/dr0_2 for other data sets. Northern Sky Narrowband Survey by Stefan Ziegenbalg.'),
    ('OHS8','NSNS OIII, H-alpha and SII','Northern Sky Narrowband Survey DR0.2 OIII H-alpha SII','simg.de/P/NSNS/DR0_2/ohs8','500.7-673 nm',64.84,'[OIII] (mapped to red), H-alpha (mapped to green), and [SII] (mapped to blue) without continuum (except for the brightest stars) as compressed 8-bit color HIPS for easy visualization. See http://www.simg.de/nebulae3/dr0_2 for other data sets. Northern Sky Narrowband Survey by Stefan Ziegenbalg.'),
    ('OIII8','NSNS OIII','Northern Sky Narrowband Survey DR0.2 DR0.2 OIII','simg.de/P/NSNS/DR0_2/oiii8','500.7 nm',64.64,'OIII at 500.7 nm (without continuum) as compressed 8-bit HIPS for easy visualization. See http://www.simg.de/nebulae3/dr0_2 for other data sets. Northern Sky Narrowband Survey by Stefan Ziegenbalg.'),
    ('FINKBEINER','Finkbeiner H-alpha','Finkbeiner H-alpha composite survey','CDS/P/Finkbeiner','480-730 nm',100,'D. Finkbeiner has assembled a full sky Halpha map using data from several surveys: the Wisconsin H-Alpha Mapper (WHAM), the Virginia Tech Spectral-Line Survey (VTSS), and the Southern H-Alpha Sky Survey Atlas (SHASSA).'),
    ('SKYMAPPER_COLOR','SkyMapper Southern Color','SkyMapper Southern Survey DR 4','CDS/P/Skymapper/DR4/color','410.46-865.33 nm',63.27,'SkyMapper Southern Survey (SMSS) fourth data release (DR4) covers 26,000 deg2 in six optical filters (u, v, g, r, i, z) from over 400,000 images acquired by the 1.3 m SkyMapper telescope between 2014-03 and 2021-09. The 6-band sky coverage extends from the South Celestial Pole to Dec = +16° , with some images reaching Dec ∼ +28°. In contrast to previous DRs, we include all good-quality images from the facility taken during that time span, not only those explicitly taken for the public Survey. From the image dataset, we produce a catalogue of over 15 billion detections made from ∼ 700 million unique astrophysical objects. The typical 10σ depths for each field range between 18.5 and 20.5 mag, depending on the filter, but certain sky regions include longer exposures that reach as deep as 22 mag in some filters. HiPS made by CDS from deep and shallow images, rejecting images with strong background variation. The color HiPS has been created from bands i, r and g. Copyright: Australian National University.'),
    ('DESI','DESI Color','DESI Legacy Surveys Color (g, r, i, z)','CDS/P/DESI-Legacy-Surveys/DR10/color','390-1020 nm',55.54,'The DESI Legacy Imaging Surveys (http://legacysurvey.org/) are a combination of three public projects (the Dark Energy Camera Legacy Survey, the Beijing-Arizona Sky Survey, and the Mayall z-band Legacy Survey) that will jointly image ≈14,000 deg2 of the extragalactic sky visible from the northern hemisphere in three optical bands (g, r, and z) using telescopes at the Kitt Peak National Observatory and the Cerro Tololo Inter-American Observatory. The combined survey footprint is split into two contiguous areas by the Galactic plane. The optical imaging is conducted using a unique strategy of dynamically adjusting the exposure times and pointing selection during observing that results in a survey of nearly uniform depth. As of DR10, the Legacy Surveys inference model is being self-consistently expanded to > 20,000 square degrees by incorporating additional DECam data from NOIRLab that includes extra optical bands (g, r, i, z). https://www.legacysurvey.org/acknowledgment/'),
    ('SDSS9_COLOR','SDSS9 color','Sloan Digital Sky Survey DR 9','CDS/P/SDSS9/color','378.2-838.9 nm',36.25,'The Sloan Digital Sky Survey is a multi-filter imaging and spectroscopic redshift survey using a dedicated 2.5-m wide-angle optical telescope at Apache Point Observatory in New Mexico, United States. Data collection began in 2000, and the final imaging data release covers over 35% of the sky. This color composition is an CDS alternative to the orignal SLOAN color composition using the g, r an i original DR9 bands with a log transfer function and specifical cuts for each band. http://www.sdss.org/');

PRAGMA user_version = 16;